python
def postageDrawerPositiveProofStrip(readings, k):
    a=readings
    out=[]
    m=max(a,default=0)
    dp=[m+1]*(m+1)
    dp[0]=0
    for x in range(1,m+1):
        for coin in (1,4,9):
            if coin<=x: dp[x]=min(dp[x],dp[x-coin]+1)
    out=[dp[x] for x in a]
    return [x for x in out if x>0]


java
class Solution {
  public int[] postageDrawerPositiveProofStrip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int m=0;for(int x:a)m=Math.max(m,x);int[]dp=new int[m+1];Arrays.fill(dp,m+1);dp[0]=0;for(int x=1;x<=m;x++)for(int coin:new int[]{1,4,9})if(coin<=x)dp[x]=Math.min(dp[x],dp[x-coin]+1);for(int x:a)out.add(dp[x]);}
    return out.stream().filter(x->x>0).mapToInt(Integer::intValue).toArray();
  }
}
